import pandas as pd
import numpy as np

class DataCleaning:
    def __init__(self):
        self.actions_log = []

    def clean(self, data: pd.DataFrame):
        data = data.copy() 

        # Check for data type consistency
        for col in data.columns:
            if col in ["IDpol", "ClaimNb", "Exposure", "VehPower", "DrivAge", "BonusMalus", "Density"]:
                if not pd.api.types.is_numeric_dtype(data[col]):
                    self.actions_log.append(f"Non-numeric values found in column {col}.")
            else:
                if pd.api.types.is_numeric_dtype(data[col]):
                    self.actions_log.append(f"Numeric values found in categorical column {col}.")

        # Handle missing values
        for col in data.columns:
            if col in ["IDpol", "ClaimNb", "Exposure", "VehPower", "DrivAge", "BonusMalus", "Density"]:
                if data[col].isnull().any():
                    data[col] = data[col].interpolate()
                    self.actions_log.append(f"Interpolated missing values in column {col}.")

        # Analyze variable distributions
        for col in data.columns:
            if col in ["IDpol", "ClaimNb", "Exposure", "VehPower", "DrivAge", "BonusMalus", "Density"]:
                Q1 = data[col].quantile(0.25)
                Q3 = data[col].quantile(0.75)
                IQR = Q3 - Q1
                if IQR == 0:
                    self.actions_log.append(f"Column {col} has no outliers.")
                else:
                    outliers = data[(data[col] < Q1 - 1.5 * IQR) | (data[col] > Q3 + 1.5 * IQR)]
                    if outliers.empty:
                        self.actions_log.append(f"No outliers found in column {col}.")
                    else:
                        data = data.drop(outliers.index)
                        self.actions_log.append(f"Dropped {len(outliers)} outliers in column {col}.")

        # Check for data consistency
        for col in data.columns:
            if col in ["Area", "VehBrand", "VehGas", "Region"]:
                if data[col].isnull().any():
                    self.actions_log.append(f"Missing values found in column {col}.")
                if data[col].duplicated().any():
                    self.actions_log.append(f"Duplicated values found in column {col}.")

        # Data normalization/scaling
        from sklearn.preprocessing import MinMaxScaler
        scaler = MinMaxScaler()
        for col in data.columns:
            if col in ["IDpol", "ClaimNb", "Exposure", "VehPower", "DrivAge", "BonusMalus", "Density"]:
                data[col] = scaler.fit_transform(data[[col]])
                self.actions_log.append(f"Normalized column {col}.")

        # Explore correlations
        corr_matrix = data.corr()
        for i in range(len(corr_matrix)):
            for j in range(i+1, len(corr_matrix)):
                if abs(corr_matrix.iloc[i, j]) > 0.7:
                    self.actions_log.append(f"High correlation between columns {data.columns[i]} and {data.columns[j]}.")
        return data
